async function guardedBatch(db: D1DatabaseLike, statements: readonly D1PreparedStatement[], message: string): Promise<readonly D1Result[]> { if (!db.batch) throw new NativeJobStoreConflictError("atomic D1 batch is required"); try { const results = await db.batch(statements); if (results.some((result) => result.success === false)) throw new NativeJobStoreConflictError(message); return results; } catch (error) { throw new NativeJobStoreConflictError(`${message}: ${String(error)}`); } }
