function validateIso(value: string): void { if (new Date(Date.parse(value)).toISOString() !== value) throw new NativeJobStoreConflictError("timestamp malformed"); }
function canonical(value: unknown): string { return JSON.stringify(value, (_key, item) => item && typeof item === "object" && !Array.isArray(item) ? Object.fromEntries(Object.entries(item).sort(([a], [b]) => a < b ? -1 : a > b ? 1 : 0)) : item); }
function sha(value: string): string { return createHash("sha256").update(value).digest("hex"); }
function slug(value: string): string { return value.replace(/[^A-Za-z0-9_.-]+/gu, "-"); }
